cases.script:
doc=$(help expect)
case "$doc" in
  *"Expect-style pty automation for bash-os."*"expect spawn CMD [ARGS...] -h FD_VAR -h PID_VAR"*"expect expect-alt FD PAT1 [PAT2 ...] [-t SEC] -V WHICH_VAR -V MATCH_VAR"*"Positive -t SEC bounds the whole wait, including while output keeps arriving."*"expect and expect-alt return 0 for a match, 1 for timeout, 2 for EOF."*) printf 'documented expect help present\n' ;;
  *) exit 1 ;;
esac
